SELECT (SELECT channel FROM marketing_campaigns m WHERE m.campaign_id = ws.campaign_id) AS ch, COUNT(session_id), COUNT(*) FILTER (WHERE added_to_cart), COUNT(*) FILTER (WHERE converted_order_id IS NOT NULL) FROM web_sessions ws WHERE ws.campaign_id IS NOT NULL AND ws.started_at_utc >= TIMESTAMP '2026-01-01' - INTERVAL 6 HOUR AND ws.started_at_utc < TIMESTAMP '2026-03-31' + INTERVAL 18 HOUR GROUP BY 1
